-- Trimmed from an export by OpenEMR 7.0.3's Administration > Backup page (Export Configuration, every layout and list)
-- of a synthetic site: the statements as mariadb-dump wrote them, fewer rows. No patient data.
SET character_set_client = utf8;
DELETE FROM layout_options WHERE form_id = "DEM";
DELETE FROM layout_options WHERE form_id = "LBFsocial";
DELETE FROM layout_group_properties WHERE grp_form_id = "LBFsocial";
SET sql_mode = '';
SET group_concat_max_len = 1000000;
SELECT CONCAT(
'ALTER TABLE patient_data ',
COALESCE(GROUP_CONCAT(DISTINCT ' ADD `', lo.field_id, '` TEXT NOT NULL' ORDER BY lo.field_id), '')
)
FROM layout_options AS lo WHERE
(lo.form_id LIKE 'DEM%' OR lo.source = 'D') AND lo.field_id NOT IN
(SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_NAME = 'patient_data')
INTO @sql;
PREPARE stmt FROM @sql;
EXECUTE stmt;
